contract OwnableVault {
 address public immutable owner;
 address public immutable treasury;
 uint256 public total;
 constructor(address nextTreasury) { require(nextTreasury != address(0)); owner = msg.sender; treasury = nextTreasury; }
 modifier onlyOwner() { require(msg.sender == owner); _; }
 function deposit() external payable { total += msg.value; }
 function withdraw(uint256 amount) external onlyOwner { require(amount <= address(this).balance); (bool ok,) = treasury.call{value: amount}(""); require(ok); }
}

